1	/**
2	 * V3 Cache Manager
3	 *
4	 * High-performance LRU cache with TTL support, memory pressure handling,
5	 * and write-through caching for the unified memory system.
6	 *
7	 * @module v3/memory/cache-manager
8	 */
9	
10	import { EventEmitter } from 'node:events';
11	import {
12	  CacheConfig,
13	  CacheStats,
14	  CachedEntry,
15	  MemoryEntry,
16	  MemoryEvent,
17	} from './types.js';
18	
19	/**
20	 * Doubly-linked list node for LRU implementation
21	 */
22	interface LRUNode<T> {
23	  key: string;
24	  value: CachedEntry<T>;
25	  prev: LRUNode<T> | null;
26	  next: LRUNode<T> | null;
27	}
28	
29	/**
30	 * High-performance LRU Cache with TTL support
31	 *
32	 * Features:
33	 * - O(1) get, set, delete operations
34	 * - LRU eviction policy
35	 * - TTL-based expiration
36	 * - Memory pressure handling
37	 * - Write-through caching support
38	 * - Performance statistics
39	 */
40	export class CacheManager<T = MemoryEntry> extends EventEmitter {
41	  private config: CacheConfig;
42	  private cache: Map<string, LRUNode<T>> = new Map();
43	  private head: LRUNode<T> | null = null;
44	  private tail: LRUNode<T> | null = null;
45	  private currentMemory: number = 0;
46	
47	  // Statistics
48	  private stats: {
49	    hits: number;
50	    misses: number;
51	    evictions: number;
52	    expirations: number;
53	    writes: number;
54	  } = {
55	    hits: 0,
56	    misses: 0,
57	    evictions: 0,
58	    expirations: 0,
59	    writes: 0,
60	  };
61	
62	  // Cleanup timer
63	  private cleanupInterval: NodeJS.Timeout | null = null;
64	
65	  constructor(config: Partial<CacheConfig> = {}) {
66	    super();
67	    this.config = this.mergeConfig(config);
68	    this.startCleanupTimer();
69	  }
70	
71	  /**
72	   * Get a value from the cache
73	   */
74	  get(key: string): T | null {
75	    const node = this.cache.get(key);
76	
77	    if (!node) {
78	      this.stats.misses++;
79	      this.emit('cache:miss', { key });
80	      return null;
81	    }
82	
83	    // Check if expired
84	    if (this.isExpired(node.value)) {
85	      this.delete(key);
86	      this.stats.misses++;
87	      this.stats.expirations++;
88	      this.emit('cache:expired', { key });
89	      return null;
90	    }
91	
92	    // Update access time and count
93	    node.value.lastAccessedAt = Date.now();
94	    node.value.accessCount++;
95	
96	    // Move to front (most recently used)
97	    this.moveToFront(node);
98	
99	    this.stats.hits++;
100	    this.emit('cache:hit', { key });
101	
102	    return node.value.data;
103	  }
104	
105	  /**
106	   * Set a value in the cache
107	   */
108	  set(key: string, data: T, ttl?: number): void {
109	    const now = Date.now();
110	    const entryTtl = ttl || this.config.ttl;
111	
112	    // Check if key already exists
113	    const existingNode = this.cache.get(key);
114	    if (existingNode) {
115	      // Update existing entry
116	      existingNode.value.data = data;
117	      existingNode.value.cachedAt = now;
118	      existingNode.value.expiresAt = now + entryTtl;
119	      existingNode.value.lastAccessedAt = now;
120	
121	      this.moveToFront(existingNode);
122	      this.stats.writes++;
123	      return;
124	    }
125	
126	    // Calculate memory for new entry
127	    const entryMemory = this.estimateSize(data);
128	
129	    // Evict entries if needed for memory pressure
130	    if (this.config.maxMemory) {
131	      while (
132	        this.currentMemory + entryMemory > this.config.maxMemory &&
133	        this.cache.size > 0
134	      ) {
135	        this.evictLRU();
136	      }
137	    }
138	
139	    // Evict entries if at capacity
140	    while (this.cache.size >= this.config.maxSize) {
141	      this.evictLRU();
142	    }
143	
144	    // Create new node
145	    const cachedEntry: CachedEntry<T> = {
146	      data,
147	      cachedAt: now,
148	      expiresAt: now + entryTtl,
149	      lastAccessedAt: now,
150	      accessCount: 0,
151	    };
152	
153	    const node: LRUNode<T> = {
154	      key,
155	      value: cachedEntry,
156	      prev: null,
157	      next: null,
158	    };
159	
160	    // Add to cache
161	    this.cache.set(key, node);
162	    this.addToFront(node);
163	    this.currentMemory += entryMemory;
164	    this.stats.writes++;
165	
166	    this.emit('cache:set', { key, ttl: entryTtl });
167	  }
168	
169	  /**
170	   * Delete a value from the cache
171	   */
172	  delete(key: string): boolean {
173	    const node = this.cache.get(key);
174	    if (!node) {
175	      return false;
176	    }
177	
178	    this.removeNode(node);
179	    this.cache.delete(key);
180	    this.currentMemory -= this.estimateSize(node.value.data);
181	
182	    this.emit('cache:delete', { key });
183	    return true;
184	  }
185	
186	  /**
187	   * Check if a key exists in the cache (without affecting LRU order)
188	   */
189	  has(key: string): boolean {
190	    const node = this.cache.get(key);
191	    if (!node) return false;
192	    if (this.isExpired(node.value)) {
193	      this.delete(key);
194	      return false;
195	    }
196	    return true;
197	  }
198	
199	  /**
200	   * Clear all entries from the cache
201	   */
202	  clear(): void {
203	    this.cache.clear();
204	    this.head = null;
205	    this.tail = null;
206	    this.currentMemory = 0;
207	
208	    this.emit('cache:cleared', { previousSize: this.cache.size });
209	  }
210	
211	  /**
212	   * Get cache statistics
213	   */
214	  getStats(): CacheStats {
215	    const total = this.stats.hits + this.stats.misses;
216	    return {
217	      size: this.cache.size,
218	      hitRate: total > 0 ? this.stats.hits / total : 0,
219	      hits: this.stats.hits,
220	      misses: this.stats.misses,
221	      evictions: this.stats.evictions,
222	      memoryUsage: this.currentMemory,
223	    };
224	  }
225	
226	  /**
227	   * Get all keys in the cache
228	   */
229	  keys(): string[] {
230	    return Array.from(this.cache.keys());
231	  }
232	
233	  /**
234	   * Get the size of the cache
235	   */
236	  get size(): number {
237	    return this.cache.size;
238	  }
239	
240	  /**
241	   * Prefetch multiple keys in a single batch
242	   */
243	  async prefetch(
244	    keys: string[],
245	    loader: (keys: string[]) => Promise<Map<string, T>>,
246	    ttl?: number
247	  ): Promise<void> {
248	    const missing = keys.filter((key) => !this.has(key));
249	
250	    if (missing.length === 0) {
251	      return;
252	    }
253	
254	    const data = await loader(missing);
255	
256	    for (const [key, value] of data) {
257	      this.set(key, value, ttl);
258	    }
259	
260	    this.emit('cache:prefetched', { keys: missing.length });
261	  }
262	
263	  /**
264	   * Get or set pattern - get from cache or load and cache
265	   */
266	  async getOrSet(
267	    key: string,
268	    loader: () => Promise<T>,
269	    ttl?: number
270	  ): Promise<T> {
271	    const cached = this.get(key);
272	    if (cached !== null) {
273	      return cached;
274	    }
275	
276	    const data = await loader();
277	    this.set(key, data, ttl);
278	    return data;
279	  }
280	
281	  /**
282	   * Warm the cache with initial data
283	   */
284	  warmUp(entries: Array<{ key: string; data: T; ttl?: number }>): void {
285	    for (const entry of entries) {
286	      this.set(entry.key, entry.data, entry.ttl);
287	    }
288	    this.emit('cache:warmedUp', { count: entries.length });
289	  }
290	
291	  /**
292	   * Invalidate entries matching a pattern
293	   */
294	  invalidatePattern(pattern: string | RegExp): number {
295	    const regex = typeof pattern === 'string' ? new RegExp(pattern) : pattern;
296	    let invalidated = 0;
297	
298	    for (const key of this.cache.keys()) {
299	      if (regex.test(key)) {
300	        this.delete(key);
301	        invalidated++;
302	      }
303	    }
304	
305	    this.emit('cache:invalidated', { pattern: pattern.toString(), count: invalidated });
306	    return invalidated;
307	  }
308	
309	  /**
310	   * Shutdown the cache manager
311	   */
312	  shutdown(): void {
313	    if (this.cleanupInterval) {
314	      clearInterval(this.cleanupInterval);
315	      this.cleanupInterval = null;
316	    }
317	    this.clear();
318	    this.emit('cache:shutdown');
319	  }
320	
321	  // ===== Private Methods =====
322	
323	  private mergeConfig(config: Partial<CacheConfig>): CacheConfig {
324	    return {
325	      maxSize: config.maxSize || 10000,
326	      ttl: config.ttl || 300000, // 5 minutes default
327	      lruEnabled: config.lruEnabled !== false,
328	      maxMemory: config.maxMemory,
329	      writeThrough: config.writeThrough || false,
330	    };
331	  }
332	
333	  private isExpired(entry: CachedEntry<T>): boolean {
334	    return Date.now() > entry.expiresAt;
335	  }
336	
337	  private estimateSize(data: T): number {
338	    try {
339	      return JSON.stringify(data).length * 2; // Rough UTF-16 estimate
340	    } catch {
341	      return 1000; // Default for non-serializable objects
342	    }
343	  }
344	
345	  private addToFront(node: LRUNode<T>): void {
346	    node.prev = null;
347	    node.next = this.head;
348	
349	    if (this.head) {
350	      this.head.prev = node;
351	    }
352	
353	    this.head = node;
354	
355	    if (!this.tail) {
356	      this.tail = node;
357	    }
358	  }
359	
360	  private removeNode(node: LRUNode<T>): void {
361	    if (node.prev) {
362	      node.prev.next = node.next;
363	    } else {
364	      this.head = node.next;
365	    }
366	
367	    if (node.next) {
368	      node.next.prev = node.prev;
369	    } else {
370	      this.tail = node.prev;
371	    }
372	  }
373	
374	  private moveToFront(node: LRUNode<T>): void {
375	    if (node === this.head) return;
376	
377	    this.removeNode(node);
378	    this.addToFront(node);
379	  }
380	
381	  private evictLRU(): void {
382	    if (!this.tail) return;
383	
384	    const evictedKey = this.tail.key;
385	    const evictedSize = this.estimateSize(this.tail.value.data);
386	
387	    this.removeNode(this.tail);
388	    this.cache.delete(evictedKey);
389	    this.currentMemory -= evictedSize;
390	    this.stats.evictions++;
391	
392	    this.emit('cache:eviction', { key: evictedKey });
393	  }
394	
395	  private startCleanupTimer(): void {
396	    // Clean up expired entries every minute
397	    this.cleanupInterval = setInterval(() => {
398	      this.cleanupExpired();
399	    }, 60000);
400	  }
401	
402	  private cleanupExpired(): void {
403	    const now = Date.now();
404	    let cleaned = 0;
405	
406	    for (const [key, node] of this.cache) {
407	      if (node.value.expiresAt < now) {
408	        this.delete(key);
409	        cleaned++;
410	      }
411	    }
412	
413	    if (cleaned > 0) {
414	      this.emit('cache:cleanup', { expired: cleaned });
415	    }
416	  }
417	}
