419	/**
420	 * Multi-layer cache with L1 (memory) and L2 (storage) tiers
421	 */
422	export class TieredCacheManager<T = MemoryEntry> extends EventEmitter {
423	  private l1Cache: CacheManager<T>;
424	  private l2Loader: ((key: string) => Promise<T | null>) | null = null;
425	  private l2Writer: ((key: string, value: T) => Promise<void>) | null = null;
426	
427	  constructor(
428	    l1Config: Partial<CacheConfig> = {},
429	    l2Options?: {
430	      loader: (key: string) => Promise<T | null>;
431	      writer?: (key: string, value: T) => Promise<void>;
432	    }
433	  ) {
434	    super();
435	    this.l1Cache = new CacheManager<T>(l1Config);
436	
437	    if (l2Options) {
438	      this.l2Loader = l2Options.loader;
439	      this.l2Writer = l2Options.writer ?? null;
440	    }
441	
442	    // Forward L1 events
443	    this.l1Cache.on('cache:hit', (data) => this.emit('l1:hit', data));
444	    this.l1Cache.on('cache:miss', (data) => this.emit('l1:miss', data));
445	    this.l1Cache.on('cache:eviction', (data) => this.emit('l1:eviction', data));
446	  }
447	
448	  /**
449	   * Get from tiered cache
450	   */
451	  async get(key: string): Promise<T | null> {
452	    // Try L1 first
453	    const l1Result = this.l1Cache.get(key);
454	    if (l1Result !== null) {
455	      return l1Result;
456	    }
457	
458	    // Try L2 if available
459	    if (this.l2Loader) {
460	      const l2Result = await this.l2Loader(key);
461	      if (l2Result !== null) {
462	        // Promote to L1
463	        this.l1Cache.set(key, l2Result);
464	        this.emit('l2:hit', { key });
465	        return l2Result;
466	      }
467	      this.emit('l2:miss', { key });
468	    }
469	
470	    return null;
471	  }
472	
473	  /**
474	   * Set in tiered cache
475	   */
476	  async set(key: string, value: T, ttl?: number): Promise<void> {
477	    // Write to L1
478	    this.l1Cache.set(key, value, ttl);
479	
480	    // Write-through to L2 if configured
481	    if (this.l2Writer) {
482	      await this.l2Writer(key, value);
483	      this.emit('l2:write', { key });
484	    }
485	  }
486	
487	  /**
488	   * Delete from tiered cache
489	   */
490	  delete(key: string): boolean {
491	    return this.l1Cache.delete(key);
492	  }
493	
494	  /**
495	   * Get L1 cache statistics
496	   */
497	  getStats(): CacheStats {
498	    return this.l1Cache.getStats();
499	  }
500	
501	  /**
502	   * Clear L1 cache
503	   */
504	  clear(): void {
505	    this.l1Cache.clear();
506	  }
507	
508	  /**
509	   * Shutdown tiered cache
510	   */
511	  shutdown(): void {
512	    this.l1Cache.shutdown();
513	  }
514	}
515	
516	export default CacheManager;
