1	/**
2	 * RuVocal Database — self-contained RVF document store.
3	 *
4	 * Zero external dependencies. All data persisted to a single
5	 * RVF JSON file on disk. MongoDB Collection interface preserved
6	 * so all 56 importing files work unchanged.
7	 */
8	
9	import type { Conversation } from "$lib/types/Conversation";
10	import type { SharedConversation } from "$lib/types/SharedConversation";
11	import type { AbortedGeneration } from "$lib/types/AbortedGeneration";
12	import type { Settings } from "$lib/types/Settings";
13	import type { User } from "$lib/types/User";
14	import type { MessageEvent } from "$lib/types/MessageEvent";
15	import type { Session } from "$lib/types/Session";
16	import type { Assistant } from "$lib/types/Assistant";
17	import type { Report } from "$lib/types/Report";
18	import type { ConversationStats } from "$lib/types/ConversationStats";
19	import type { MigrationResult } from "$lib/types/MigrationResult";
20	import type { Semaphore } from "$lib/types/Semaphore";
21	import type { AssistantStats } from "$lib/types/AssistantStats";
22	import type { TokenCache } from "$lib/types/TokenCache";
23	import type { ConfigKey } from "$lib/types/ConfigKey";
24	
25	import { building } from "$app/environment";
26	import { onExit } from "./exitHandler";
27	import { join, dirname } from "path";
28	import { fileURLToPath } from "url";
29	import { existsSync, mkdirSync } from "fs";
30	
31	import {
32		RvfCollection,
33		RvfGridFSBucket,
34		initRvfStore,
35		flushToDisk,
36	} from "./database/rvf";
37	
38	export const CONVERSATION_STATS_COLLECTION = "conversations.stats";
39	
40	export class Database {
41		private static instance: Database;
42		private initialized = false;
43	
44		private async init() {
45			const dbFolder =
46				process.env.RVF_DB_PATH ||
47				join(dirname(fileURLToPath(import.meta.url)), "../../../db");
48	
49			if (!existsSync(dbFolder)) {
50				mkdirSync(dbFolder, { recursive: true });
51			}
52	
53			const dbPath = join(dbFolder, "ruvocal.rvf.json");
54	
55			console.log(`[RuVocal] Database: ${dbPath}`);
56			initRvfStore(dbPath);
57			this.initialized = true;
58	
59			// Flush to disk on exit
60			onExit(async () => {
61				console.log("[RuVocal] Flushing database to disk");
62				flushToDisk();
63			});
64		}
65	
66		public static async getInstance(): Promise<Database> {
67			if (!Database.instance) {
68				Database.instance = new Database();
69				await Database.instance.init();
70			}
71			return Database.instance;
72		}
73	
74		public getClient() {
75			if (!this.initialized) {
76				throw new Error("Database not initialized");
77			}
78			return {}; // No external client — self-contained
79		}
80	
81		public getCollections() {
82			if (!this.initialized) {
83				throw new Error("Database not initialized");
84			}
85	
86			const conversations = new RvfCollection<Conversation>("conversations");
87			const settings = new RvfCollection<Settings>("settings");
88			const users = new RvfCollection<User>("users");
89			const sessions = new RvfCollection<Session>("sessions");
90			const messageEvents = new RvfCollection<MessageEvent>("messageEvents");
91			const abortedGenerations = new RvfCollection<AbortedGeneration>("abortedGenerations");
92			const semaphores = new RvfCollection<Semaphore>("semaphores");
93			const tokenCaches = new RvfCollection<TokenCache>("tokens");
94			const configCollection = new RvfCollection<ConfigKey>("config");
95			const migrationResults = new RvfCollection<MigrationResult>("migrationResults");
96			const sharedConversations = new RvfCollection<SharedConversation>("sharedConversations");
97			const assistants = new RvfCollection<Assistant>("assistants");
98			const assistantStats = new RvfCollection<AssistantStats>("assistants.stats");
99			const conversationStats = new RvfCollection<ConversationStats>(CONVERSATION_STATS_COLLECTION);
100			const reports = new RvfCollection<Report>("reports");
101			const tools = new RvfCollection<Record<string, unknown>>("tools");
102			const bucket = new RvfGridFSBucket();
103	
104			return {
105				conversations,
106				conversationStats,
107				assistants,
108				assistantStats,
109				reports,
110				sharedConversations,
111				abortedGenerations,
112				settings,
113				users,
114				sessions,
115				messageEvents,
116				bucket,
117				migrationResults,
118				semaphores,
119				tokenCaches,
120				tools,
121				config: configCollection,
122			};
123		}
124	}
125	
126	export let collections: ReturnType<typeof Database.prototype.getCollections>;
127	
128	export const ready = (async () => {
129		if (!building) {
130			const db = await Database.getInstance();
131			collections = db.getCollections();
132		} else {
133			collections = {} as unknown as ReturnType<typeof Database.prototype.getCollections>;
134		}
135	})();
136	
137	export async function getCollectionsEarly(): Promise<
138		ReturnType<typeof Database.prototype.getCollections>
139	> {
140		await ready;
141		if (!collections) {
142			throw new Error("Database not initialized");
143		}
144		return collections;
145	}
