1	/**
2	 * @claude-flow/memory - V3 Unified Memory System
3	 *
4	 * Provides a unified memory interface backed by AgentDB with HNSW indexing
5	 * for 150x-12,500x faster vector search compared to brute-force approaches.
6	 *
7	 * @module @claude-flow/memory
8	 *
9	 * @example
10	 * ```typescript
11	 * import { UnifiedMemoryService, query, QueryTemplates } from '@claude-flow/memory';
12	 *
13	 * // Initialize the memory service
14	 * const memory = new UnifiedMemoryService({
15	 *   dimensions: 1536,
16	 *   cacheEnabled: true,
17	 *   embeddingGenerator: async (text) => embeddings.embed(text),
18	 * });
19	 *
20	 * await memory.initialize();
21	 *
22	 * // Store entries
23	 * await memory.store({
24	 *   key: 'auth-patterns',
25	 *   content: 'OAuth 2.0 implementation patterns for secure authentication',
26	 *   tags: ['auth', 'security', 'patterns'],
27	 * });
28	 *
29	 * // Semantic search
30	 * const results = await memory.semanticSearch('user authentication best practices', 5);
31	 *
32	 * // Query with fluent builder
33	 * const entries = await memory.query(
34	 *   query()
35	 *     .semantic('security vulnerabilities')
36	 *     .inNamespace('security')
37	 *     .withTags(['critical'])
38	 *     .threshold(0.8)
39	 *     .limit(10)
40	 *     .build()
41	 * );
42	 * ```
43	 */
44	
45	// ===== Core Types =====
46	export type {
47	  // Memory Entry Types
48	  MemoryType,
49	  AccessLevel,
50	  ConsistencyLevel,
51	  DistanceMetric,
52	  MemoryEntry,
53	  MemoryEntryInput,
54	  MemoryEntryUpdate,
55	
56	  // Query Types
57	  QueryType,
58	  MemoryQuery,
59	  SearchResult,
60	  SearchOptions,
61	
62	  // HNSW Types
63	  HNSWConfig,
64	  HNSWStats,
65	  QuantizationConfig,
66	
67	  // Backend Types
68	  IMemoryBackend,
69	  BackendStats,
70	  HealthCheckResult,
71	  ComponentHealth,
72	
73	  // Cache Types
74	  CacheConfig,
75	  CacheStats,
76	  CachedEntry,
77	
78	  // Migration Types
79	  MigrationSource,
80	  MigrationConfig,
81	  MigrationProgress,
82	  MigrationResult,
83	  MigrationError,
84	
85	  // Event Types
86	  MemoryEventType,
87	  MemoryEvent,
88	  MemoryEventHandler,
89	
90	  // SONA Types
91	  SONAMode,
92	  LearningPattern,
93	
94	  // Utility Types
95	  EmbeddingGenerator,
96	  BatchEmbeddingGenerator,
97	} from './types.js';
98	
99	// Utility Functions and Constants (runtime values)
100	export {
101	  generateMemoryId,
102	  createDefaultEntry,
103	  PERFORMANCE_TARGETS,
104	} from './types.js';
