847	/**
848	 * Create a hybrid memory service (SQLite + AgentDB).
849	 *
850	 * This is the DEFAULT recommended configuration per ADR-009. ADR-125 Phase 2
851	 * delivers the real wiring: the returned service's backend is a `HybridBackend`
852	 * created through `createDatabase({ provider: 'hybrid' })`, not an AgentDB-only
853	 * downgrade as in earlier versions.
854	 *
855	 * @example
856	 * ```typescript
857	 * const memory = await createHybridService('./data/memory.db', embeddingFn);
858	 * await memory.initialize();
859	 *
860	 * // Structured queries go to SQLite
861	 * const user = await memory.getByKey('users', 'john@example.com');
862	 *
863	 * // Semantic queries go to AgentDB
864	 * const similar = await memory.semanticSearch('authentication patterns', 10);
865	 *
866	 * // Verify the backend is actually hybrid
867	 * import { HybridBackend } from '@claude-flow/memory';
868	 * memory.backend instanceof HybridBackend; // true
869	 * ```
870	 */
871	export async function createHybridService(
872	  databasePath: string,
873	  embeddingGenerator: EmbeddingGenerator,
874	  dimensions: number = 1536
875	): Promise<UnifiedMemoryService> {
876	  const { createDatabase } = await import('./database-provider.js');
877	  const hybridBackend = await createDatabase(databasePath, {
878	    provider: 'hybrid',
879	    embeddingGenerator,
880	    dimensions,
881	  });
882	  const service = new UnifiedMemoryService({
883	    embeddingGenerator,
884	    dimensions,
885	    autoEmbed: true,
886	    cacheEnabled: true,
887	    persistenceEnabled: true,
888	    persistencePath: databasePath,
889	  });
890	  return service.withBackend(hybridBackend);
891	}
